+<!DOCTYPE html>
+<html lang="en">
+<head>
+  <meta charset="UTF-8">
+  <meta name="viewport" content="width=device-width, initial-scale=1.0">
+  <title>Computer Languages Quiz</title>
+  <style>
+    :root {
+      color-scheme: dark;
+      --bg: #080b12;
+      --panel: #111827;
+      --panel-soft: #172033;
+      --text: #f8fafc;
+      --muted: #9ca3af;
+      --accent: #7c3aed;
+      --accent-bright: #a78bfa;
+      --border: rgba(148, 163, 184, 0.22);
+      --shadow: 0 24px 80px rgba(0, 0, 0, 0.45);
+    }
+
+    * {
+      box-sizing: border-box;
+    }
+
+    body {
+      margin: 0;
+      min-height: 100vh;
+      display: grid;
+      place-items: center;
+      padding: 32px 16px;
+      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
+      color: var(--text);
+      background:
+        radial-gradient(circle at top left, rgba(124, 58, 237, 0.28), transparent 34rem),
+        radial-gradient(circle at bottom right, rgba(14, 165, 233, 0.18), transparent 30rem),
+        var(--bg);
+    }
+
+    main {
+      width: min(100%, 820px);
+    }
+
+    .quiz-card {
+      padding: clamp(24px, 5vw, 44px);
+      border: 1px solid var(--border);
+      border-radius: 28px;
+      background: linear-gradient(145deg, rgba(17, 24, 39, 0.95), rgba(15, 23, 42, 0.86));
+      box-shadow: var(--shadow);
+      backdrop-filter: blur(18px);
+    }
+
+    .eyebrow {
+      margin: 0 0 10px;
+      color: var(--accent-bright);
+      font-size: 0.78rem;
+      font-weight: 800;
+      letter-spacing: 0.14em;
+      text-transform: uppercase;
+    }
+
+    h1 {
+      margin: 0;
+      font-size: clamp(2rem, 6vw, 3.7rem);
+      line-height: 1;
+      letter-spacing: -0.06em;
+    }
+
+    .intro {
+      max-width: 620px;
+      margin: 18px 0 32px;
+      color: var(--muted);
+      font-size: 1.03rem;
+      line-height: 1.7;
+    }
+
+    form {
+      display: grid;
+      gap: 22px;
+    }
+
+    .form-field {
+      padding: 22px;
+      border: 1px solid var(--border);
+      border-radius: 22px;
+      background: rgba(15, 23, 42, 0.72);
+    }
+
+    legend {
+      float: left;
+      width: 100%;
+      margin-bottom: 12px;
+      font-size: 1.15rem;
+      font-weight: 800;
+      line-height: 1.35;
+    }
+
+    fieldset {
+      min-width: 0;
+      margin: 0;
+      padding: 0;
+      border: 0;
+    }
+
+    .help-text {
+      clear: both;
+      margin: 0 0 18px;
+      color: var(--muted);
+      font-size: 0.95rem;
+      line-height: 1.5;
+    }
+
+    .choice-grid {
+      clear: both;
+      display: grid;
+      grid-template-columns: repeat(2, minmax(0, 1fr));
+      gap: 12px;
+    }
+
+    .choice {
+      position: relative;
+      display: flex;
+      align-items: center;
+      gap: 12px;
+      min-height: 54px;
+      padding: 14px 15px;
+      border: 1px solid var(--border);
+      border-radius: 16px;
+      background: var(--panel-soft);
+      color: #e5e7eb;
+      cursor: pointer;
+      transition: border-color 180ms ease, background 180ms ease, transform 180ms ease;
+    }
+
+    .choice:hover {
+      transform: translateY(-1px);
+      border-color: rgba(167, 139, 250, 0.72);
+      background: rgba(30, 41, 59, 0.95);
+    }
+
+    .choice input {
+      width: 18px;
+      height: 18px;
+      margin: 0;
+      accent-color: var(--accent);
+    }
+
+    .choice span {
+      font-weight: 650;
+    }
+
+    .actions {
+      display: flex;
+      justify-content: flex-end;
+      padding-top: 4px;
+    }
+
+    button {
+      border: 0;
+      border-radius: 999px;
+      padding: 15px 26px;
+      color: white;
+      background: linear-gradient(135deg, var(--accent), #2563eb);
+      box-shadow: 0 14px 34px rgba(124, 58, 237, 0.36);
+      font: inherit;
+      font-weight: 800;
+      cursor: pointer;
+      transition: transform 180ms ease, filter 180ms ease;
+    }
+
+    button:hover {
+      transform: translateY(-2px);
+      filter: brightness(1.08);
+    }
+
+    button:focus-visible,
+    .choice:has(input:focus-visible) {
+      outline: 3px solid rgba(167, 139, 250, 0.46);
+      outline-offset: 3px;
+    }
+
+    @media (max-width: 640px) {
+      .choice-grid {
+        grid-template-columns: 1fr;
+      }
+
+      .actions {
+        justify-content: stretch;
+      }
+
+      button {
+        width: 100%;
+      }
+    }
+  </style>
+</head>
+<body>
+  <main id="app"></main>
+
+  <script>
+    const quizQuestions = [
+      {
+        id: "language-paradigms",
+        prompt: "Which of these computer languages are commonly used for object-oriented programming?",
+        helpText: "Choose every answer that applies. Each question can have more than one correct choice.",
+        choices: ["Java", "C#", "HTML", "Python"]
+      },
+      {
+        id: "web-languages",
+        prompt: "Which languages are core technologies for building web pages in the browser?",
+        choices: ["HTML", "CSS", "SQL", "JavaScript"]
+      },
+      {
+        id: "data-languages",
+        prompt: "Which languages are frequently used for data analysis or scientific computing?",
+        choices: ["Python", "R", "Fortran", "Bash"]
+      }
+    ];
+
+    function Choice({ questionId, label }) {
+      const value = label.toLowerCase().replace(/[^a-z0-9]+/g, "-");
+
+      return `
+        <label class="choice">
+          <input type="checkbox" name="${questionId}" value="${value}">
+          <span>${label}</span>
+        </label>
+      `;
+    }
+
+    function QuestionField({ question, index }) {
+      const helpText = question.helpText
+        ? `<p class="help-text" id="${question.id}-help">${question.helpText}</p>`
+        : "";
+      const describedBy = question.helpText ? ` aria-describedby="${question.id}-help"` : "";
+
+      return `
+        <div class="form-field">
+          <fieldset${describedBy}>
+            <legend>${index + 1}. ${question.prompt}</legend>
+            ${helpText}
+            <div class="choice-grid">
+              ${question.choices.map((choice) => Choice({ questionId: question.id, label: choice })).join("")}
+            </div>
+          </fieldset>
+        </div>
+      `;
+    }
+
+    function QuizApp({ questions }) {
+      return `
+        <section class="quiz-card" aria-labelledby="quiz-title">
+          <p class="eyebrow">Multi-select quiz</p>
+          <h1 id="quiz-title">Computer Languages</h1>
+          <p class="intro">
+            Test your knowledge of programming and markup languages. Select all answers that fit each question.
+          </p>
+          <form>
+            ${questions.map((question, index) => QuestionField({ question, index })).join("")}
+            <div class="actions">
+              <button type="submit">Submit answers</button>
+            </div>
+          </form>
+        </section>
+      `;
+    }
+
+    document.querySelector("#app").innerHTML = QuizApp({ questions: quizQuestions });
+  </script>
+</body>
+</html>
*** End Patch
